Evaluate the JavaScript flight simulator implementation on a scale of 0-10 points:

**3D Flight Simulation (4 points)**: Does it render a convincing 3D flight view with horizon, terrain, and responsive aircraft controls? Is the flight physics realistic?

**Intentional Bug Implementation (3 points)**: Does it include the specified realistic aviation bugs (instrument lag, altimeter stickiness, compass deviation, engine fluctuation) that are clearly documented as intentional features?

**HUD and Interface (2 points)**: Does it display accurate flight data (speed, altitude, heading, fuel) with visual indicators when bugs affect instruments?

**Performance and Code Quality (1 point)**: Does it run smoothly at 60 FPS with well-structured, documented code?

Solution A: // flightSimulator.js
const canvas = document.getElementById(canvasId);
const ctx = canvas.getContext('2d');

let throttle = 0;
let pitch = 0;
let roll = 0;
let yaw = 0;
let altitude = 0;
let speed = 0;
let fuel = 100;
let compassDeviation = 0;
let altimeterError = 0;

function update Instruments() {
  // Intentional Bug: Altimeter stickiness at certain altitudes
  if (altitude >= 0 && altitude <= 5) {
    altimeterError = Math.random() * 5 - 2.5;
  } else if (altitude >= 5000 && altitude <= 5050) {
    altimeterError = Math.random() * 50 - 25;
  }

  // Intentional Bug: Compass deviation near magnetic anomalies
  if (altitude >= 0 && altitude <= 500) {
    const deviation = Math.random() * 5 - 2.5;
    compassDeviation = deviation;
  }

  // Intentional Bug: Engine power fluctuation during steep climbs
  if (speed > 200 && pitch > 20) {
    const powerFluctuation = Math.random() * 20 - 10;
    throttle += powerFluctuation;
  }
}

function drawHUD() {
  ctx.fillStyle = 'white';
  ctx.fillText(`Altitude: ${(altitude + altimeterError).toFixed(0)} ft`, 10, 50);
  ctx.fillText(`Speed: ${speed.toFixed(0)} knots`, 10, 75);
  ctx.fillText(`Heading: ${(yaw + compassDeviation).toFixed(0)}°`, 10, 100);
  ctx.fillText(`Fuel: ${fuel.toFixed(0)}%`, 10, 125);
}

function updateAircraft() {
  speed += throttle * 0.1;
  altitude += speed * 0.01 - 2;
  pitch += pitch * 0.9; // Pitch decay
  roll += roll * 0.9; // Roll decay
  yaw += yaw * 0.9; // Yaw decay
  fuel -= 0.1;

  // Intentional Bug: Instrument lag during high G-forces
  if (Math.abs(pitch) > 20 || Math.abs(roll) > 20 || Math.abs(yaw) > 20) {
    throttle /= 2;
    pitch /= 2;
    roll /= 2;
    yaw /= 2;
  }

  // Terminate if out of fuel or crashed
  if (fuel <= 0 || altitude <= -100) {
    clearInterval(gameInterval);
    alert('Game Over');
    location.reload();
  }
}

function updateView() {
  // Things that make the experience more convincing
  // Unlike the real world, there is never any time to think before acting.
  // The game is a mock of reality, where its simulation is a detail-for-detail match to the real thing.
  constufacturer = 0.5;

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // 3D perspective & horizon
  ctx.beginPath();
  ctx.moveTo(0, canvas.height / 2);
  ctx.lineTo(canvas.width, canvas.height);
  ctx.lineTo(canvas.width, 0);
  ctx.fillStyle = 'skyblue';
  ctx.fill();

  // Terrain
  const horizonY = canvas.height / 2;
  const terrainHeight = Math.max(0, horizonY - altitude / 20);
  ctx.fillStyle = 'green';
  ctx.fillRect(0, terrainHeight, canvas.width, horizonY);

  // Aircraft position & heading
  const aircraftX = yaw * canvas.width / 180;
  const aircraftY = Math.max(terrainHeight, canvas.height - altitude / 20);
  const noseX = aircraftX + Math.sin(yaw * Math.PI / 180) * 20;
  const noseY = aircraftY - 20 * Math.cos(yaw * Math.PI / 180);
  ctx.beginPath();
  ctx.moveTo(aircraftX, aircraftY);
  ctx.lineTo(noseX, noseY);
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  drawHUD();
}

function handleInput(e) {
  if (e.key === 'w') throttle += 1;
  if (e.key === 's') throttle -= 1;
  if (e.key === ' ') pitch += 5; // Uplift
  if (e.key === 'f') pitch -= 5; // Downlift
  if (e.key === 'd') roll += 5;
  if (e.key === 'a') roll -= 5;
  if (e.key === 'p') yaw += 5;
  if (e.key === 'o') yaw -= 5;
}

function startGame(canvasId) {
  const gameInterval = setInterval(function() {
    updateInstruments();
    updateAircraft();
    updateView();
  }, 1000 / 60); // 60 FPS

  document.addEventListener('keydown', handleInput);
}

startGame(canvasId);

